changeSet.sql:
INSERT INTO permissions (name, description) VALUES ('plugin_webfilter_access', 'Has access to web filter configuration');
INSERT INTO userRolePermissions (roleId, permissionId)
    SELECT id, currval('permissions_id_seq')
    FROM userroles;

CREATE TABLE plugin_webfilter_policies (
    id serial NOT NULL CONSTRAINT plugin_webfilter_policies_pr_key PRIMARY KEY,
    configurationId INT NOT NULL REFERENCES configurations (id) ON DELETE CASCADE,
    customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    dnsDomain VARCHAR(255),
    filterActive BOOLEAN NOT NULL DEFAULT FALSE,
    updatedAt BIGINT NOT NULL
);
ALTER TABLE plugin_webfilter_policies ADD CONSTRAINT plugin_webfilter_policies_config_unique UNIQUE (configurationId);

CREATE TABLE plugin_webfilter_categories (
    id serial NOT NULL CONSTRAINT plugin_webfilter_categories_pr_key PRIMARY KEY,
    policyId INT NOT NULL REFERENCES plugin_webfilter_policies (id) ON DELETE CASCADE,
    categoryId VARCHAR(50) NOT NULL,
    blocked BOOLEAN NOT NULL
);
ALTER TABLE plugin_webfilter_categories ADD CONSTRAINT plugin_webfilter_categories_policy_category_unique UNIQUE (policyId, categoryId);

CREATE TABLE plugin_webfilter_entries (
    id serial NOT NULL CONSTRAINT plugin_webfilter_entries_pr_key PRIMARY KEY,
    policyId INT NOT NULL REFERENCES plugin_webfilter_policies (id) ON DELETE CASCADE,
    kind VARCHAR(20) NOT NULL,
    value VARCHAR(500) NOT NULL
);
ALTER TABLE plugin_webfilter_entries ADD CONSTRAINT plugin_webfilter_entries_policy_kind_value_unique UNIQUE (policyId, kind, value);

CREATE TABLE plugin_webfilter_locked_history (
    id serial NOT NULL CONSTRAINT plugin_webfilter_locked_history_pr_key PRIMARY KEY,
    policyId INT NOT NULL REFERENCES plugin_webfilter_policies (id) ON DELETE CASCADE,
    packageName VARCHAR(255) NOT NULL,
    lockedAt BIGINT NOT NULL
);

CREATE TABLE plugin_webfilter_settings (
    id serial NOT NULL CONSTRAINT plugin_webfilter_settings_pr_key PRIMARY KEY,
    customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    sourcesJson TEXT,
    appCatalogJson TEXT
);
ALTER TABLE plugin_webfilter_settings ADD CONSTRAINT plugin_webfilter_settings_customer_unique UNIQUE (customerId);
